import{_ as e,o,c as r,a3 as s}from"./chunks/framework.CZBGEXos.js";const n="/manual/img/personas/listado.png",t="/manual/img/personas/nueva-persona.png",b=JSON.parse('{"title":"Personas","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/personas.md","filePath":"modulos/personas.md"}'),i={name:"modulos/personas.md"};function l(d,a,c,u,p,g){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="personas" tabindex="-1">Personas <a class="header-anchor" href="#personas" aria-label="Permalink to &quot;Personas&quot;">​</a></h1><p>El módulo de <strong>Personas</strong> es el registro de todos los trabajadores y usuarios de tu empresa. Aquí das de alta a cada persona, defines su <strong>rol</strong> (qué puede hacer en la plataforma) y su <strong>cargo</strong> (qué hace en la obra), y la asignas a los proyectos donde trabajará.</p><p>Tener bien cargadas a las personas es importante: de ellas dependen las asignaciones de documentos, las firmas, el onboarding de cada obra y las capacitaciones.</p><h2 id="entrar-al-modulo" tabindex="-1">Entrar al módulo <a class="header-anchor" href="#entrar-al-modulo" aria-label="Permalink to &quot;Entrar al módulo&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Personas</strong> (o <strong>Equipo</strong>, según tu rol). Verás el listado de las personas de tu empresa, con un buscador <strong>&quot;Buscar por nombre o RUT…&quot;</strong> para encontrarlas rápido.</p><p><img src="'+n+'" alt="Listado de personas con los botones Nueva persona y Carga masiva"></p><h2 id="agregar-una-persona" tabindex="-1">Agregar una persona <a class="header-anchor" href="#agregar-una-persona" aria-label="Permalink to &quot;Agregar una persona&quot;">​</a></h2><ol><li>Haz clic en el botón <strong>Nueva persona</strong> (arriba a la derecha).</li><li>Completa el formulario, organizado en secciones:</li></ol><h3 id="datos-personales" tabindex="-1">Datos personales <a class="header-anchor" href="#datos-personales" aria-label="Permalink to &quot;Datos personales&quot;">​</a></h3><ul><li><strong>RUT</strong> <em>(obligatorio)</em> — el RUT de la persona (ej.: <em>12.345.678-9</em>).</li><li><strong>Nombre</strong> <em>(obligatorio)</em>, <strong>Apellido paterno</strong> y <strong>Apellido materno</strong>.</li><li><strong>Fecha de nacimiento</strong> y <strong>Email</strong> <em>(opcionales)</em>.</li></ul><h3 id="acceso-y-rol" tabindex="-1">Acceso y rol <a class="header-anchor" href="#acceso-y-rol" aria-label="Permalink to &quot;Acceso y rol&quot;">​</a></h3><ul><li><strong>Rol</strong> <em>(obligatorio)</em> — define <strong>qué puede hacer</strong> la persona en la plataforma (Administrador, Prevencionista, Jefe de Obra, Supervisor o Trabajador). Revisa <a href="/manual/roles/">Roles de Usuario</a> antes de elegir.</li><li><strong>Cargo DS44</strong> — el cargo que desempeña en obra (carpintero, soldador, etc.). El cargo determina qué documentos y capacitaciones de onboarding necesitará.</li><li><strong>Nivel de escolaridad</strong> <em>(opcional)</em>.</li><li><strong>Acceso web</strong> — indica si la persona podrá iniciar sesión en la plataforma desde un computador o teléfono.</li></ul><h3 id="asignacion-a-obras" tabindex="-1">Asignación a obras <a class="header-anchor" href="#asignacion-a-obras" aria-label="Permalink to &quot;Asignación a obras&quot;">​</a></h3><p>Marca las <strong>obras</strong> a las que se asignará la persona desde el inicio. Puedes cambiarlo después desde su perfil o desde la pestaña Equipo de cada obra.</p><h3 id="contacto-de-emergencia-opcional" tabindex="-1">Contacto de emergencia (opcional) <a class="header-anchor" href="#contacto-de-emergencia-opcional" aria-label="Permalink to &quot;Contacto de emergencia (opcional)&quot;">​</a></h3><p>Datos de un contacto para el expediente del trabajador (nombre, relación, teléfono).</p><ol start="3"><li>Guarda. La persona quedará registrada y lista para asignarle documentos y actividades.</li></ol><p><img src="'+t+'" alt="Formulario de nueva persona con las secciones de datos, rol y obras"></p><blockquote><p>💡 <strong>Rol ≠ Cargo.</strong> El <strong>rol</strong> es el nivel de acceso en el sistema (qué pantallas y acciones puede usar). El <strong>cargo</strong> es su oficio en la obra (qué documentos de seguridad le corresponden). Una misma persona tiene un rol y uno o más cargos.</p></blockquote><h2 id="carga-masiva" tabindex="-1">Carga masiva <a class="header-anchor" href="#carga-masiva" aria-label="Permalink to &quot;Carga masiva&quot;">​</a></h2><p>Si necesitas registrar a muchas personas de una vez, usa el botón <strong>Carga masiva</strong>. Te permite subir un archivo con varios trabajadores en lugar de crearlos uno por uno: ideal al poner en marcha una obra grande.</p><h2 id="ver-y-editar-una-persona" tabindex="-1">Ver y editar una persona <a class="header-anchor" href="#ver-y-editar-una-persona" aria-label="Permalink to &quot;Ver y editar una persona&quot;">​</a></h2><p>Haz clic sobre una persona para abrir su <strong>perfil</strong>, donde puedes revisar y actualizar sus datos, ver sus obras asignadas, sus documentos y su estado de onboarding.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>¿Qué diferencia hay entre rol y cargo?</strong> El <strong>rol</strong> define los permisos en la plataforma (qué puede ver y hacer). El <strong>cargo</strong> define su trabajo en obra y, con ello, qué documentos y capacitaciones de seguridad necesita. Son dos cosas distintas y ambas importan.</p><p><strong>Creé a la persona pero no puede iniciar sesión.</strong> Verifica que tenga marcado el <strong>Acceso web</strong> y que tenga un email válido. Las personas sin acceso web quedan registradas para el expediente, pero no entran a la plataforma.</p><p><strong>¿Puedo asignar una persona a varias obras?</strong> Sí. Una persona puede trabajar en varias obras a la vez, cada una con su cargo correspondiente.</p><p><strong>Tengo que cargar 50 trabajadores. ¿Hay una forma rápida?</strong> Sí, usa <strong>Carga masiva</strong> para subirlos todos juntos desde un archivo, en vez de crearlos uno a uno.</p><p><strong>¿Quién puede crear o editar personas?</strong> Principalmente los roles de gestión (Administrador, Prevencionista, Jefe de Obra según el caso). Consulta <a href="/manual/roles/">Roles de Usuario</a> para el detalle de permisos.</p><p><strong>Una persona dejó la empresa. ¿La elimino?</strong> En general conviene <strong>desactivarla</strong> en lugar de borrarla, para conservar el historial de sus firmas y documentos (importante para una eventual fiscalización).</p>',30)])])}const h=e(i,[["render",l]]);export{b as __pageData,h as default};
